export function PlanningScreen(props:Props){return <ProposalForm {...props}/>;}
function ProposalForm({storeId,proposal,proposals=[],stops=[],notice,appointments=[],now=Date.now(),onSubmit,onReorder}:Props){
 const [form,setForm]=useState<Proposal>({title:'',fileId:''});
 const [selected,setSelected]=useState('');
 const [reason,setReason]=useState('');
 const [slot,setSlot]=useState('');
 const available=useMemo(()=>[...(proposal?[proposal]:[]),...proposals].filter(p=>"'!p.storeId||p.storeId===storeId),[proposal,proposals,storeId]);
 const active=stops.filter(s=>!s.removed).sort((a,b)=>a.position-b.position);
 const chosen=active.find(s=>s.id===selected);
 const needsReason=chosen?screenRequiresReason(chosen):false;
 const at=slot?new Date(slot).getTime():NaN;
 const scheduleValid=!notice||!slot||fitsWindow(at,notice,appointments,now);
 const reasonValid=!needsReason||reason.trim().length>0;
 const reorder=(index:number)=>{const move=moveUp(active,index);if(!move)return;const target=active[index];const why=screenRequiresReason(target)?reason.trim():undefined;if(screenRequiresReason(target)&&!why)return;onReorder?.({...move,...(why?{reason:why}:{})});};
 return <section>
  <form onSubmit={e=>{e.preventDefault();if(!scheduleValid||!reasonValid)return;onSubmit({storeId,...form,...(slot?{scheduledAt:at}:{})});}}>
   <label>Title<input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label>
   <label>File ID<input aria-label="File ID" value={form.fileId} onChange={e=>setForm({...form,fileId:e.target.value})}/></label>
   <label>Upload proposal<select aria-label="Upload proposal" value={available.some(p=>p.fileId===form.fileId)?form.fileId:'"''} onChange={e=>{const p=available.find(x=>x.fileId===e.target.value);if(p){setForm({title:p.title,fileId:p.fileId});}}}><option value=\"\">Choose upload</option>{available.map(p=><option key={p.fileId} value={p.fileId}>{p.title}</option>)}</select></label>
   <button type=\"button\" onClick={()=>{const p=available[0];if(p)setForm({title:p.title,fileId:p.fileId});}}>Use upload</button>
   {notice&&<label>Schedule<input aria-label=\"Schedule\" type=\"datetime-local\" value={slot} onChange={e=>setSlot(e.target.value)}/></label>}
   {"'!scheduleValid&&<p role="alert">Choose a time on or after the notification and before the next appointment.</p>}
   {!reasonValid&&<p role="alert">Enter a reason for changing this stop.</p>}
   <button type="submit" disabled={!scheduleValid||!reasonValid}>Save</button>
  </form>
  {active.length>0&&<section aria-label="Delivery stops"><h2>Delivery stops</h2>{active.map((stop,index)=><div key={stop.id}><span>{stop.position}. {stop.id} ({stop.status})</span><button type="button" aria-label={`Move ${stop.id} up`} disabled={index===0} onClick={()=>{setSelected(stop.id);reorder(index);}}>Move up</button></div>)}</section>}
  {active.some(screenRequiresReason)&&<label>Reason<input aria-label="Reason" value={reason} onChange={e=>setReason(e.target.value)}/></label>}
  {active.length>0&&<label>Stop requiring reason<select aria-label="Stop requiring reason" value={selected} onChange={e=>{setSelected(e.target.value);setReason('"'');}}><option value=\"\">Select stop</option>{active.filter(screenRequiresReason).map(s=><option key={s.id} value={s.id}>{s.id}</option>)}</select></label>}
 </section>;
}
EOF
